    <script>
        function ultraSmoothScroll(targetY, duration = 1000) {
  const startY = window.scrollY;
  const diff = targetY - startY;
  const startTime = performance.now();

  function scrollFrame(now) {
    const elapsed = now - startTime;
    const progress = Math.min(elapsed / duration, 1);
    const eased = 1 - Math.pow(1 - progress, 3); // easeOutCubic
    window.scrollTo(0, startY + diff * eased);
    if (progress < 1) requestAnimationFrame(scrollFrame);
  }

  requestAnimationFrame(scrollFrame);
}

document.querySelectorAll('.ultra-smooth-scroll').forEach(button => {
  button.addEventListener('click', function (e) {
    e.preventDefault();
    const target = this.getAttribute('data-target');

    if (target === 'top') {
      ultraSmoothScroll(0); // Scroll to top
    } else {
      const targetEl = document.querySelector(target);
      if (targetEl) ultraSmoothScroll(targetEl.offsetTop);
    }
  });
});

  </script>
